import { useState } from "react";
import {
  GraduationCap,
  User,
  Building2,
  Mail,
  Lock,
  Eye,
  EyeOff,
  ArrowRight,
  Shield,
  CheckCircle2
} from 'lucide-react';
import StudentDashboard from "../StudentDashboard";
import MentorDashboard from "../MentorDashboard";
import PlacementDashboard from "../PlacementDashboard";

const ProfessionalLogin = () => {
  const [selectedUserType, setSelectedUserType] = useState('');
  const [showLogin, setShowLogin] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [loginData, setLoginData] = useState({
    email: '',
    password: ''
  });
  const [loginError, setLoginError] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authenticatedUser, setAuthenticatedUser] = useState(null);

  const VALID_CREDENTIALS = {
    'student': { email: 'student@college.edu', password: 'student123' },
    'mentor': { email: 'mentor@college.edu', password: 'mentor123' },
    'placement-cell': { email: 'placement@college.edu', password: 'placement123' }
  };

  const userTypes = [
    {
      id: 'student',
      title: 'Student',
      subtitle: 'Access Your Career Portal',
      description: 'Track applications, find internships, and connect with mentors',
      icon: User,
      color: 'bg-gray-900',
      bgColor: 'bg-gray-50',
      iconBg: 'bg-gray-100',
      iconColor: 'text-gray-700'
    },
    {
      id: 'mentor',
      title: 'Mentor',
      subtitle: 'Guide Student Success',
      description: 'Support students, review applications, and monitor progress',
      icon: GraduationCap,
      color: 'bg-gray-900',
      bgColor: 'bg-gray-50',
      iconBg: 'bg-gray-100',
      iconColor: 'text-gray-700'
    },
    {
      id: 'placement-cell',
      title: 'Placement Officer',
      subtitle: 'Manage Campus Recruitment',
      description: 'Coordinate companies, manage drives, and analyze placement data',
      icon: Building2,
      color: 'bg-gray-900',
      bgColor: 'bg-gray-50',
      iconBg: 'bg-gray-100',
      iconColor: 'text-gray-700'
    }
  ];

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoginError('');
    setIsLoading(true);

    const creds = VALID_CREDENTIALS[selectedUserType];

    setTimeout(() => {
      if (loginData.email === creds.email && loginData.password === creds.password) {
        setIsAuthenticated(true);
        setAuthenticatedUser({
          email: loginData.email,
          userType: selectedUserType,
          name: selectedUserType.charAt(0).toUpperCase() + selectedUserType.slice(1)
        });
      } else {
        setLoginError('Invalid email or password. Please try again.');
      }
      setIsLoading(false);
    }, 1000);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setAuthenticatedUser(null);
    setSelectedUserType('');
    setShowLogin(false);
    setLoginData({ email: '', password: '' });
    setLoginError('');
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setLoginData(prev => ({
      ...prev,
      [name]: value
    }));
    setLoginError('');
  };

  // Show appropriate dashboard if authenticated
  if (isAuthenticated && authenticatedUser) {
    switch (authenticatedUser.userType) {
      case 'student':
        return <StudentDashboard onLogout={handleLogout} />;
      case 'mentor':
        return <MentorDashboard onLogout={handleLogout} />;
      case 'placement-cell':
        return <PlacementDashboard onLogout={handleLogout} />;
      default:
        return null;
    }
  }

  // Login form for selected user type
  if (showLogin && selectedUserType) {
    const userTypeData = userTypes.find(type => type.id === selectedUserType);

    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6">
        <div className="max-w-md w-full">
          {/* Back Button */}
          <button
            onClick={() => {
              setShowLogin(false);
              setSelectedUserType('');
              setLoginError('');
            }}
            className="mb-6 flex items-center text-gray-600 hover:text-gray-900 font-medium transition-colors"
          >
            <ArrowRight className="h-5 w-5 mr-2 rotate-180" />
            Back to selection
          </button>

          {/* Login Card */}
          <div className="bg-white border border-gray-200 overflow-hidden">
            {/* Header */}
            <div className={`p-8 ${userTypeData.color}`}>
              <div className="flex items-center justify-center mb-4">
                <div className="p-4 bg-white border border-gray-200">
                  <userTypeData.icon className="h-12 w-12 text-gray-900" />
                </div>
              </div>
              <h2 className="text-2xl font-semibold text-white text-center mb-2">
                {userTypeData.title} Login
              </h2>
              <p className="text-white text-center text-sm">
                {userTypeData.subtitle}
              </p>
            </div>

            {/* Form */}
            <form onSubmit={handleLogin} className="p-8">
              {/* Error Message */}
              {loginError && (
                <div className="mb-6 p-4 bg-gray-50 border border-gray-300">
                  <p className="text-gray-900 text-sm font-medium text-center flex items-center justify-center">
                    <Shield className="h-4 w-4 mr-2" />
                    {loginError}
                  </p>
                </div>
              )}

              {/* Info Notice */}
              <div className="mb-6 p-4 bg-gray-50 border border-gray-200">
                <p className="text-gray-700 text-sm text-center">
                  Please use your institutional email to sign in
                </p>
              </div>

              {/* Email Field */}
              <div className="mb-6">
                <label className="block text-gray-700 text-sm font-medium mb-2">
                  Email Address
                </label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
                  <input
                    type="email"
                    name="email"
                    value={loginData.email}
                    onChange={handleInputChange}
                    className="w-full pl-12 pr-4 py-3 border border-gray-300 focus:outline-none focus:border-gray-900 transition-colors"
                    placeholder="you@college.edu"
                    required
                  />
                </div>
              </div>

              {/* Password Field */}
              <div className="mb-6">
                <label className="block text-gray-700 text-sm font-medium mb-2">
                  Password
                </label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    name="password"
                    value={loginData.password}
                    onChange={handleInputChange}
                    className="w-full pl-12 pr-12 py-3 border border-gray-300 focus:outline-none focus:border-gray-900 transition-colors"
                    placeholder="Enter your password"
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  >
                    {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                  </button>
                </div>
              </div>

              {/* Submit Button */}
              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-3 px-6 bg-gray-900 hover:bg-gray-800 text-white font-medium transition-all disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isLoading ? (
                  <div className="flex items-center justify-center">
                    <div className="animate-spin h-5 w-5 border-2 border-white border-t-transparent mr-3"></div>
                    Signing in...
                  </div>
                ) : (
                  <div className="flex items-center justify-center">
                    Sign In
                    <ArrowRight className="h-5 w-5 ml-2" />
                  </div>
                )}
              </button>

              {/* Demo Credentials */}
              <div className="mt-6 p-4 bg-gray-50 border border-gray-200">
                <p className="text-xs text-gray-600 text-center font-medium mb-2">Demo Credentials:</p>
                <p className="text-xs text-gray-700 text-center">
                  <strong>Email:</strong> {VALID_CREDENTIALS[selectedUserType].email}<br />
                  <strong>Password:</strong> {VALID_CREDENTIALS[selectedUserType].password}
                </p>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }

  // User type selection (home page)
  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center">
              <div className="p-2 bg-gray-900 mr-3">
                <GraduationCap className="h-6 w-6 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-gray-900">CampusConnect</h1>
                <p className="text-xs text-gray-600">Career Development Platform</p>
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-6 py-12">
        {/* Hero Section */}
        <div className="text-center mb-16">
          <h2 className="text-5xl font-semibold text-gray-900 mb-4">
            Welcome to <span className="text-gray-900">CampusConnect</span>
          </h2>

        </div>

        {/* User Type Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-16">
          {userTypes.map((userType) => {
            const Icon = userType.icon;
            return (
              <div
                key={userType.id}
                onClick={() => {
                  setSelectedUserType(userType.id);
                  setShowLogin(true);
                }}
                className="bg-white rounded-2xl shadow-lg hover:shadow-2xl transform hover:-translate-y-2 transition-all duration-300 cursor-pointer overflow-hidden group"
              >
                <div className={`p-8 bg-gradient-to-r ${userType.color}`}>
                  <div className="flex justify-center mb-4">
                    <div className="p-4 bg-white/20 backdrop-blur-sm rounded-2xl group-hover:scale-110 transition-transform duration-300">
                      <Icon className="h-12 w-12 text-white" />
                    </div>
                  </div>
                  <h3 className="text-2xl font-bold text-white text-center mb-2">
                    {userType.title}
                  </h3>
                  <p className="text-white/90 text-center text-sm">
                    {userType.subtitle}
                  </p>
                </div>
                <div className="p-6">
                  <p className="text-slate-600 text-center mb-4">
                    {userType.description}
                  </p>
                  <button className="w-full py-3 px-6 bg-slate-900 hover:bg-slate-800 text-white font-semibold rounded-xl transition-colors flex items-center justify-center">
                    Get Started
                    <ArrowRight className="h-5 w-5 ml-2" />
                  </button>
                </div>
              </div>
            );
          })}
        </div>


      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 mt-16">
        <div className="max-w-7xl mx-auto px-6 py-8">
          <div className="text-center text-slate-600 text-sm">
            <p>© 2025 CampusConnect. All rights reserved.</p>
            <p className="mt-2">Need help? Contact support@campusconnect.edu</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default ProfessionalLogin;
